DELIMITER $$
CREATE TRIGGER `trg_camp_occupancy_delete` AFTER DELETE ON `camp_assignments` FOR EACH ROW BEGIN
    IF OLD.is_active = 1 THEN
        UPDATE relief_camps 
        SET updated_at = CURRENT_TIMESTAMP
        WHERE id = OLD.camp_id;
    END IF;
END
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `trg_camp_occupancy_insert` AFTER INSERT ON `camp_assignments` FOR EACH ROW BEGIN
    IF NEW.is_active = 1 THEN
        UPDATE relief_camps 
        SET updated_at = CURRENT_TIMESTAMP
        WHERE id = NEW.camp_id;
    END IF;
END
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `trg_camp_occupancy_update` AFTER UPDATE ON `camp_assignments` FOR EACH ROW BEGIN
    IF OLD.is_active != NEW.is_active THEN
        UPDATE relief_camps 
        SET updated_at = CURRENT_TIMESTAMP
        WHERE id = NEW.camp_id;
    END IF;
END
$$
DELIMITER ;

