DROP TABLE IF EXISTS `vw_camp_occupancy`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `vw_camp_occupancy`  AS SELECT `rc`.`id` AS `camp_id`, `rc`.`tenant_id` AS `tenant_id`, `rc`.`name` AS `camp_name`, `rc`.`capacity` AS `capacity`, count(`ca`.`id`) AS `current_occupancy`, coalesce(sum(`af`.`family_size`),0) AS `total_people`, `rc`.`capacity`- count(`ca`.`id`) AS `available_capacity` FROM ((`relief_camps` `rc` left join `camp_assignments` `ca` on(`rc`.`id` = `ca`.`camp_id` and `ca`.`is_active` = 1)) left join `affected_families` `af` on(`ca`.`family_id` = `af`.`id`)) WHERE `rc`.`is_active` = 1 GROUP BY `rc`.`id`, `rc`.`tenant_id`, `rc`.`name`, `rc`.`capacity` ;

